import{esc,button,number,input,select}from'../phase4/ui.js';
import{total}from'./b07-model.js';
const labels=['整板 · 每板100','整条 · 每条10','散颗 · 每颗1','整组 · 每组1000'];
const repeat=(n,fn)=>Array.from({length:n},(_,i)=>fn(i)).join('');
const flat=()=>'<i class="b7-flat" aria-label="一百格">'+repeat(100,()=>'<b></b>')+'</i>';
const piece=(u,form)=>u===0?flat():u===1?'<i class="b7-rod" aria-label="十格一条">'+repeat(10,()=>'<b></b>')+'</i>':'<i class="b7-one" aria-label="一颗"></i>';
function blocks(u,form='blocks',money=false){return `<div class="b7-blocks ${form==='sticks'?'sticks':''}">${[0,1,2].map(k=>`<section><h3>${money?['100元代币','10元代币','1元代币'][k]:labels[k]}</h3><div class="b7-pieces">${repeat(u[k],()=>money?`<i class="b7-coin">${[100,10,1][k]}</i>`:piece(k,form))||'<span class="b7-empty">空着</span>'}</div><p>${u[k]} ${money?'枚':k===0?'板':k===1?'条':'颗'}</p></section>`).join('')}</div>${u[3]?`<div class="b7-thousand"><b>一个千 · 十板百放在一起</b><div>${repeat(10,flat)}</div></div>`:''}`;}
const adders=(side='',max=2)=>`<div class="b7-adders">${Array.from({length:max+1},(_,i)=>`<div>${button('pv-add','＋ '+(i===0?'一板':i===1?'一条':'一颗'),`data-index="${i}" data-delta="1" data-side="${side}"`)}${button('pv-add','−',`data-index="${i}" data-delta="-1" data-side="${side}" aria-label="拿走${i===0?'一板':i===1?'一条':'一颗'}${side==='a'?'左边':side==='b'?'右边':''}"`)}</div>`).join('')}</div>`;
function exchanges(t,m){const entries=[['up1','十颗合一条',m.u[2]>=10],['down1','拆开一条',m.u[1]>=1],...(t.n>=100||t.type==='x-pvshift'?[['up10','十条合一板',m.u[1]>=10],['down10','拆开一板',m.u[0]>=1]]:[]),...(t.n>=1000?[['up100','十板合一千',m.u[0]>=10],['down100','拆开一千',m.u[3]>=1]]:[])];return`<div class="b7-exchanges">${entries.map(([k,l,on])=>button('pv-swap',l,`data-kind="${k}" ${on?'':'disabled'}`)).join('')}</div>`;}
function axis(max,markers){return`<svg class="b7-axis" viewBox="0 0 720 100" role="img" aria-label="零到${max}的数轴"><path d="M30 54H690"/>${repeat(11,i=>{const x=30+i*66;return`<path d="M${x} 48v12"/><text x="${x}" y="84">${max*i/10}</text>`;})}${markers.map(({value,label,color},i)=>`<path class="marker" style="color:${color||'#c16039'}" d="M${30+660*value/max} 18v35"/><circle style="fill:${color||'#c16039'}" cx="${30+660*value/max}" cy="54" r="6"/><text x="${Math.max(36,Math.min(684,30+660*value/max))}" y="${i%2?35:13}">${esc(label??'●')}</text>`).join('')}</svg>`;}
const slider=(key,label,value,max,hide=false)=>`<label class="field">${label}<input type="range" min="0" max="${max}" step="1" value="${value}" data-xfield="${key}" aria-label="${label}">${hide?'':`<output data-xvalue="${key}">${value}</output>`}</label>`;
const why=(m)=>select('why','换装后，你看到了什么',m.why,[['same','只换装法，没有添取，总量保持'],['zero','空位要留0，其他数位才不会挪错'],['pieces','块数越少，总量越少'],['drop','空位直接删掉就可以']]);
export function visual(t,m){switch(t.type){
 case'x-pvbench':return`${t.label?`<div class="b7-label">${esc(t.label)}</div>`:''}${t.forms?`<div class="b7-forms">${t.forms.map(f=>button('pv-form',f==='blocks'?'方块':'线条和点',`data-form="${f}" aria-pressed="${m.form===f}"`)).join('')}</div>`:''}${blocks(m.u,m.form,t.money)}${!t.fixed?adders():''}${exchanges(t,m)}${t.saveCount||t.forms?`${button('pv-save','留下这一种')}<div class="b7-saved">${m.saved.map(s=>`<span>${s.form==='sticks'?'简图':'方块'}：${s.u[0]}板 ${s.u[1]}条 ${s.u[2]}颗${s.u[3]?' 和一千':''}</span>`).join('')}</div>`:''}${t.position?axis(t.max,[{value:m.mark,label:m.touched?m.mark:'?'}]):''}${t.chart?`<details class="b7-chart"><summary>在百数表找同一个数</summary><div>${repeat(t.chart,i=>button('pv-cell',i+1,`data-index="${i+1}" aria-pressed="${m.cell===i+1}"`))}</div></details>`:''}`;
 case'x-pvshift':return`<p class="b7-label">原来 ${t.start} ${m.committed!==null?`· 先前猜 ${m.committed}`:''}</p>${blocks(m.u)}${m.committed===null?'<p>先在下面写猜想，再开始添取。</p>':`<div class="b7-moves">${[-100,-10,10,100].filter(d=>t.start>=100||Math.abs(d)===10).map(d=>button('pv-move',`${d>0?'添':'拿走'}${Math.abs(d)===100?'一板':'一条'}`,`data-delta="${d}"`)).join('')}</div>${exchanges(t,m)}<p class="muted">已添取：${m.moves.length?m.moves.map(x=>x>0?'＋'+x:String(x)).join('，'):'还没有'}</p>`}`;
 case'x-pvcompare':return`<div class="b7-compare">${['a','b'].map(k=>`<section><h3>${k==='a'?'左边':'右边'}：${t[k]}</h3>${blocks(m[k])}${adders(k)}</section>`).join('')}</div>`;
 case'x-pvline':return axis(t.max,[{value:t.readPoint?t.n:m.mark,label:'?'}]);
 case'x-pvorder':return`<div class="b7-order">${t.values.map((n,i)=>button('pv-order',n,`data-index="${i}" aria-pressed="${m.order.includes(i)}"`)).join('')}</div><p>从小到大：${m.order.map(i=>t.values[i]).join(' → ')||'点卡片排队'}</p>${axis(t.max,m.positions.map((value,i)=>({value,label:m.touched[i]?t.values[i]:'?',color:['#af502e','#39756d','#6964a3','#876b26'][i]})))}`;
 case'x-pvestimate':return`${m.committed!==null?`<p>先前估计 ${m.committed} · 现在已标记 ${m.taps.length}</p>`:''}<div class="b7-scatter">${repeat(t.n,i=>button('pv-tap',m.taps.includes(i)?m.taps.indexOf(i)+1:'',`data-index="${i}" style="--turn:${(i*37)%20-10}deg" ${m.committed===null?'disabled':''} aria-label="第${i+1}颗" aria-pressed="${m.taps.includes(i)}"`))}</div>`;
 case'x-pvpair':{const used=m.pairs.flat();return`<div class="b7-loose">${repeat(t.n,i=>used.includes(i)?'':button('pv-pair','●',`data-index="${i}" aria-label="珠子${i+1}" aria-pressed="${m.selected===i}"`))||'<span>这里没有剩下的珠子</span>'}</div><div class="b7-pairs">${m.pairs.map((p,i)=>button('pv-unpair','●　●',`data-index="${i}" aria-label="拆开第${i+1}对"`)).join('')}</div>${t.equation?`<p class="b7-label">${t.n} = ${m.a??'?'} + ${m.b??'?'}</p>`:''}`;}
}return'';}
export function controls(t,m){switch(t.type){
 case'x-pvbench':return number('answer','总量写成数字',m.answer)+(t.expanded?[['百的部分值多少',0],['十的部分值多少',1],['一的部分值多少',2]].map(([l,i])=>number('parts.'+i,l,m.parts[i])).join(''):'')+(t.words?t.words.map((n,i)=>input('words.'+i,n+'的中文名字',m.words[i])).join(''):'')+(t.position?slider('mark','放到数轴的位置',m.mark,t.max):'')+(t.packReport?number('packs','一共能装几包十颗',m.packs)+number('remainder','剩几颗',m.remainder):'')+(t.why?why(m):'');
 case'x-pvshift':return m.committed===null?number('guess','先猜最后的总数',m.guess)+button('pv-predict','留下猜想，动手检查'):number('answer','现在一共多少',m.answer)+select('changed','与原来相比，哪些位置的数字变了',m.changed,[['t','十位'],['h','百位'],['o','个位'],['ht','百位和十位'],['hto','百位、十位和个位']]);
 case'x-pvcompare':return select('relation',`${t.a} 与 ${t.b} 的关系`,m.relation,[['<','小于 <'],['=','等于 ='],['>','大于 >']])+select('first','从大单位往小单位看，哪里先分出了大小',m.first,[['h','百'],['t','十'],['o','一'],['same','每一位都相同']]);
 case'x-pvline':return(t.readPoint?number('estimate','这个点大约表示多少',m.estimate):slider('mark','移动这个点',m.mark,t.max,!!t.tolerance))+(t.near?number('left','左边最近的整十或整百',m.left)+number('right','右边最近的整十或整百',m.right):'');
 case'x-pvorder':return t.values.map((n,i)=>slider('positions.'+i,`移动 ${n} 的位置`,m.positions[i],t.max)).join('');
 case'x-pvestimate':return m.committed===null?number('guess','先估大约有多少',m.guess)+button('pv-predict','留下估计，再数清楚'):number('answer','数清后，一共有多少',m.answer);
 case'x-pvpair':return number('pairsCount','配成几对',m.pairsCount)+number('leftover','剩几颗',m.leftover)+select('kind','这些珠子属于哪一种',m.kind,[['even','每颗都有伴 · 偶数'],['odd','最后剩一颗 · 奇数']])+(t.equation?m.counts.map((v,i)=>number('counts.'+i,`数到第${i+1}对，共几颗`,v)).join('')+number('a','左边这一组有几颗',m.a)+number('b','右边这一组有几颗',m.b):'');
}return'';}
export const render=(t,m)=>`<section class="b7-work"><div id="extra-visual">${visual(t,m)}</div><div class="extra-controls">${controls(t,m)}</div></section>`;
